hs() { helm status inventory --kube-context main -n inv -o json 2>/dev/null; }
check "release inventory's latest revision is deployed" bash -c "helm status inventory --kube-context main -n inv 2>/dev/null | grep -q 'STATUS: deployed' && helm history inventory --kube-context main -n inv --max 1 2>/dev/null | tail -1 | grep -q deployed"
check "release keeps its history (revision 1 still listed, not re-installed)" bash -c "helm history inventory --kube-context main -n inv 2>/dev/null | awk 'NR>1{print \$1}' | grep -qx 1 && [ \$(helm history inventory --kube-context main -n inv 2>/dev/null | awk 'NR>1' | wc -l) -ge 3 ]"
check "release values: replicaCount 3, image.tag 1.28-alpine" bash -c "v=\$(helm get values inventory --kube-context main -n inv -a -o json 2>/dev/null | tr -d ' '); case \"\$v\" in *'\"replicaCount\":3'*) ;; *) exit 1;; esac; case \"\$v\" in *'\"tag\":\"1.28-alpine\"'*) ;; *) exit 1;; esac"
check "deployment inventory runs 3 ready nginx:1.28-alpine pods" bash -c "[ \"\$(kubectl --context main -n inv get deploy inventory -o jsonpath='{.spec.template.spec.containers[0].image} {.status.readyReplicas} {.status.updatedReplicas}')\" = 'nginx:1.28-alpine 3 3' ]"
